// 有限私人照护粮资源必要门；只验证钱货和事务边界，不伪造实际喂养/出生事件。
#include "resident/domains/family/birth_care_resources.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;
// 单项失败保原名，统计不掩盖未执行门。
void check(bool value,const char* name){++checks;if(!value)throw std::runtime_error(name);}
// 组件只模拟同候选已登记接受账的存在性；未登记时即使有Common头也不放行。
struct OwnerRead final:ReservationOwnerRead {bool accepted=false;bool reservation_exists(const ReservationRef& r)const override{return accepted&&r.kind==ReservationRef::Kind::contract&&r.id=="family_birth:1";}};
// 总量只用于守恒核验，不作为准入、可支配量或已提供照护的依据。
Integer total_food(const CommonStore& c){Integer result=0;for(const auto& row:c.state().inventories.rows())for(const auto& lot:row.second.lots)if(lot.item_id=="food")result+=lot.quantity;return result;}
}
int main(){try{auto catalog=std::make_shared<CommonCatalog>();catalog->places.insert("home",{"home","town",{}});catalog->items.insert("food",{"food",1,1,false,false});CommonState seed;seed.identity.world_id[0]=8;seed.identity.execution_epoch=3;seed.identity.revision=2;seed.metadata.ruleset_id=dynamic_ruleset_id;seed.metadata.player_actor_id="parent";seed.next_instance_id=20;ActorRecord actor;actor.id="parent";actor.alive=true;actor.available=true;actor.location=SettlementLocation{"town","home"};actor.inventory_id="bag";seed.actors.insert(actor.id,actor);const Owner own{Owner::Kind::actor,"parent",{}},foreign{Owner::Kind::actor,"other",{}};InventoryView bag{"bag",own,200,0,{{"lot:2","food",{},8,own,{},{ }},{"lot:3","food",{},50,foreign,{},{}}},{}};seed.inventories.insert("bag",bag);seed.inventories.insert("elsewhere",{"elsewhere",own,100,0,{},{}});seed.wallets.insert("money",{"money",own,10,{},{}});CommonStore c(seed,catalog);OwnerRead owners;c.bind_reservation_owners(&owners);BirthCareTerms terms{"other","parent","parent","home","bag","food","baby",540,2,2,3,{}};auto before=encode_common_state(c.state());auto quote=preview_birth_care_supply(c,terms);check(quote.ok&&quote.value.quantity==6&&quote.value.available_before==8,"own unreserved finite supply");check(compare_boundary(before,encode_common_state(c.state())).exact(),"preview touched supply or IDs");auto too_much=terms;too_much.prepaid_care_periods=5;check(!preview_birth_care_supply(c,too_much).ok,"foreign cargo used for childcare");check(!reserve_birth_care_recipe(c,quote.value,"family_birth:1").ok,"unallocated contract held food");check(c.append_fact({"family_birth:1","family_birth_accepted","family_birth"}).ok,"append accepted source head");check(!reserve_birth_care_recipe(c,quote.value,"family_birth:1").ok,"header without typed owner accepted");owners.accepted=true;auto recipe=reserve_birth_care_recipe(c,quote.value,"family_birth:1");check(recipe.ok,"actual accepted responsibility reserve quote");auto atomic=recipe.value;atomic.operations.push_back(WalletDelta{"missing",1,true});auto original=encode_common_state(c.state());check(!c.apply_resources(atomic).ok&&compare_boundary(original,encode_common_state(c.state())).exact(),"late recipe failure left held grain or allocated lot");auto sum=total_food(c);check(c.apply_resources(recipe.value).ok&&validate_birth_care_reservation(c,terms,"family_birth:1",6).ok,"exact contract six units held");check(total_food(c)==sum&&c.count("bag","food",{own}).value==2,"reservation consumed or duplicated food");check(!reserve_birth_care_recipe(c,quote.value,"family_birth:1").ok,"stale replay doubled reservation");auto consume=consume_birth_care_recipe(c,terms,"family_birth:1",6,2);check(consume.ok&&c.apply_resources(consume.value).ok,"one actual finite care ration recipe");check(total_food(c)==sum-2&&validate_birth_care_reservation(c,terms,"family_birth:1",4).ok,"actual food consumption did not reduce exact held source");check(!consume_birth_care_recipe(c,terms,"family_birth:1",4,1).ok,"partial undocumented care consumption accepted");c.state().wallets.find("money")->reserved.push_back({{ReservationRef::Kind::contract,"family_birth:1"},1});check(!release_birth_care_recipe(c,terms,"family_birth:1",4).ok,"unexpected cash released with food contract");c.state().wallets.find("money")->reserved.clear();auto release=release_birth_care_recipe(c,terms,"family_birth:1",4);check(release.ok&&c.apply_resources(release.value).ok&&total_food(c)==sum-2,"release refunded consumed food or transferred property");check(validate_birth_care_reservation(c,terms,"family_birth:1",0).ok&&c.count("bag","food",{own}).value==6,"remaining original food not released");check(!release_birth_care_recipe(c,terms,"family_birth:1",4).ok,"second stale release admitted");auto public_terms=terms;c.state().inventories.find("bag")->owner={Owner::Kind::organization,"public",{}};check(!preview_birth_care_supply(c,public_terms).ok,"public inventory treated as personal");std::cout<<"BIRTH_CARE_RESOURCES "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<"BIRTH_CARE_RESOURCES "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
